  step_t tb_step = STEP_IDLE;
  int unsigned errors = 0;

  // One clock drives the functional clock and jtagLtsm_clock; the core uses
  // whichever testModeLtsm selects. clk_en stops it around mode changes.
  bit clk_en = 0;
  logic tb_clk = 1'b0;
  always #5ns tb_clk = ~tb_clk;
  assign clock = clk_en & tb_clk;
  assign jtagLtsm_clock = clk_en & tb_clk;
  assign jtagFdi_clock = 1'b0;
  assign jtagRdi_clock = 1'b0;
  assign jtag_clock = 1'b0;
  assign jtag_sb_rx_clk = 1'b0;
  assign sb_rx_clk = 1'b0;

  function automatic void fail(input string msg);
    errors++;
    $error("[%s] %s", tb_step.name(), msg);
    if (errors >= 10) $fatal(1, "too many errors");
  endfunction

  task automatic cycles(input int unsigned n);
    repeat (n) @(negedge tb_clk);
  endtask

