  // Partner die: one message per rising edge of jtagLtsm_sb_rx_valid.
  task automatic send_msg(input logic [127:0] msg, input string name);
    jtagLtsm_sb_rx_dout = msg;
    jtagLtsm_sb_rx_valid = 1'b1;
    cycles(1);
    jtagLtsm_sb_rx_valid = 1'b0;
    cycles(1);
    $display("%t  partner -> LTSM: %s", $time, name);
  endtask

  task automatic send_partner_sbinit();
    send_msg(SBINIT_CLK_PATTERN, "SBINIT clock pattern");
    send_msg(SBINIT_CLK_PATTERN, "SBINIT clock pattern");
    send_msg(SBINIT_OOR_SUCCESS, "SBINIT out of reset success");
    send_msg(SBINIT_DONE_REQ, "SBINIT done req");
    send_msg(SBINIT_DONE_RESP, "SBINIT done resp");
  endtask

  task automatic wait_state(input logic [3:0] s, input string name);
    for (int unsigned c = 0; jtagLtsm_state != s; c++) begin
      if (c == STATE_TIMEOUT) $fatal(1, "[%s] LTSM did not reach %s (state %0d)", tb_step.name(), name, jtagLtsm_state);
      cycles(1);
    end
    $display("%t  LTSM state -> %s (%0d)", $time, name, s);
  endtask

