  always @(posedge jtagLtsm_clock)
    if (testModeLtsm && jtagLtsm_sb_tx_valid)
      $display("%t  LTSM -> partner: %s", $time,
        jtagLtsm_sb_tx_din == SBINIT_CLK_PATTERN ? "SBINIT clock pattern" :
        jtagLtsm_sb_tx_din == SBINIT_OOR_SUCCESS ? "SBINIT out of reset success" :
        jtagLtsm_sb_tx_din == SBINIT_DONE_REQ    ? "SBINIT done req" :
        jtagLtsm_sb_tx_din == SBINIT_DONE_RESP   ? "SBINIT done resp" :
        $sformatf("%032h", jtagLtsm_sb_tx_din));

  initial begin : run_test
    testModeDigital = 1'b0;
    testModeFdi = 1'b0;
    testModeRdi = 1'b0;
    testModeLtsm = 1'b0;
    testModePhy = 1'b0;
    zero_inputs();
    cycles_1us = CYCLES_1US;

    // ---- 1: normal operation, stimulus on jtagLtsm_* only -----------------
    tb_step = NORMAL_INJECT;
    reset_n = 1'b0;
    clk_en = 1;
    cycles(5);
    reset_n = 1'b1;
    cycles(20);
    if (dut.u_core.ltsm.state !== LT_RESET) fail("LTSM not in RESET before injection");
    take_snapshot();
    fork
      begin : inject
        jtagLtsm_reset_n = 1'b1;
        jtagLtsm_start = 1'b1;
        jtagLtsm_stable_clk = 1'b1;
        jtagLtsm_pll_locked = 1'b1;
        jtagLtsm_stable_supply = 1'b1;
        jtagLtsm_sb_tx_ready = 1'b1;
        cycles(20);
        send_partner_sbinit();
        jtag_ltsm_inputs_all_ones();
        cycles(ALL_ONES_CYCLES);
      end
      begin : watch
        forever begin
          @(posedge tb_clk); #1ns;
          check_unchanged();
          if (tdr_outs !== '0) fail("jtagLtsm_* output not 0 in normal mode");
        end
      end
    join_any
    disable fork;
    if (dut.u_core.ltsm.state !== LT_RESET) fail("LTSM left RESET in normal mode");
    $display("%t  step 1 done: LTSM ignored the jtagLtsm_* inputs in normal mode", $time);

    // ---- 2: LTSM test mode, drive the LTSM to MBINIT ----------------------
    tb_step = LTSM_TO_MBINIT;
    zero_jtag_ltsm_inputs();
    reset_n = 1'b0;
    jtagLtsm_reset_n = 1'b0;
    cycles(2);
    clk_en = 0;
    #20ns;
    testModeLtsm = 1'b1;
    #20ns;
    clk_en = 1;
    cycles(5);
    reset_n = 1'b1;
    jtagLtsm_reset_n = 1'b1;
    jtagLtsm_sb_tx_ready = 1'b1;
    jtagLtsm_stable_clk = 1'b1;
    jtagLtsm_pll_locked = 1'b1;
    jtagLtsm_stable_supply = 1'b1;
    jtagLtsm_start = 1'b1;
    wait_state(LT_SBINIT_PATTERN, "SBINIT pattern");
    send_msg(SBINIT_CLK_PATTERN, "SBINIT clock pattern");
    send_msg(SBINIT_CLK_PATTERN, "SBINIT clock pattern");
    wait_state(LT_SBINIT_OOR, "SBINIT out of reset");
    send_msg(SBINIT_OOR_SUCCESS, "SBINIT out of reset success");
    wait_state(LT_SBINIT_DONE, "SBINIT done");
    send_msg(SBINIT_DONE_REQ, "SBINIT done req");
    send_msg(SBINIT_DONE_RESP, "SBINIT done resp");
    wait_state(LT_MBINIT, "MBINIT");

    // ---- 3: every jtagLtsm_* input at 1 for ALL_ONES_CYCLES ----------------
    tb_step = ALL_ONES;
    jtag_ltsm_inputs_all_ones();
    repeat (ALL_ONES_CYCLES) begin
      @(posedge tb_clk); #1ns;
      check_ltsm_inputs_all_ones();
    end
    $display("%t  step 3 done: all jtagLtsm_* inputs read 1 inside the LTSM for %0d cycles (LTSM state %0d)",
             $time, ALL_ONES_CYCLES, jtagLtsm_state);

    // ---- 4: back to normal operation ---------------------------------------
    tb_step = BACK_TO_NORMAL;
    reset_n = 1'b0;
    jtagLtsm_reset_n = 1'b0;
    cycles(2);
    clk_en = 0;
    #20ns;
    testModeLtsm = 1'b0;
    zero_jtag_ltsm_inputs();
    #20ns;
    clk_en = 1;
    cycles(2);
    reset_n = 1'b1;
    cycles(BACK_TO_NORMAL_CYCLES);
    if (dut.u_core.ltsm.state !== LT_RESET) fail("LTSM not in RESET after returning to normal mode");
    if (tdr_outs !== '0) fail("jtagLtsm_* output not 0 after returning to normal mode");

    tb_step = DONE;
    if (errors != 0) $fatal(1, "FAIL: %0d errors", errors);
    $display("PASS: testModeLtsm directed: jtagLtsm_* ignored in normal mode, LTSM driven to MBINIT through jtagLtsm_*, all inputs reach the LTSM");
    $finish;
  end
endmodule

`default_nettype wire
